export function matchSynergy(pack) {
  if (!pack?.food) return null;
  const hit = SYNERGIES.find(s => s.food === pack.food && (!s.tool || s.tool === pack.tool));
  if (hit) return hit;
  if (pack.wish === 'token-apang') {
    return { id: 'wish-apang', whisper: '带着旧书巷伞约，团子多半会拐去厦门鼓浪屿墙头找大橘晒太阳', cardId: 'cn-xiamen', npcId: 'apang' };
  }
  if (pack.wish === 'token-manman') {
    return { id: 'wish-manman', whisper: '水母瓶微微发亮，团子似乎想去桂林漓江或海岛听水声', cardId: 'cn-guilin', npcId: 'manman' };
  }
  if (pack.wish === 'wish-grandma') {
    return { id: 'wish-grandma', whisper: '旧邮票带着远方寄语，团子正想去北京故宫红墙下看初雪', cardId: 'cn-beijing', npcId: 'grandpa' };
  }
  return null;
}

